template <typename T, int Threads, int TileH, int TileW, int TileC>
__global__ void __launch_bounds__(Threads)
depthwise2d_vertical_tiled_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int C, int H, int W_in,
    int K, int stride, int padding, int dilation,
    int H_out, int W_out)
{
  static_assert(TileW % 4 == 0, "TileW must be a multiple of 4");
  constexpr int VecOut = 4;
  constexpr int QThreads = TileW / VecOut;
  static_assert(Threads % QThreads == 0, "Threads must be a multiple of TileW/4");
  static_assert(TileH % (Threads / QThreads) == 0, "Invalid row tiling");
  constexpr int RowGroups = Threads / QThreads;
  constexpr int PVec = TileH / RowGroups;

  const int tid = threadIdx.x;

  const int w_tiles = (W_out + TileW - 1) / TileW;
  const int h_tiles = (H_out + TileH - 1) / TileH;
  const int tiles_per_image = w_tiles * h_tiles;

  const int linear_tile = blockIdx.x;
  const int n = linear_tile / tiles_per_image;
  const int rem = linear_tile - n * tiles_per_image;
  const int tile_h_idx = rem / w_tiles;
  const int tile_w_idx = rem - tile_h_idx * w_tiles;

  const int oh0 = tile_h_idx * TileH;
  const int ow0 = tile_w_idx * TileW;
  const int c_base = blockIdx.y * TileC;

  int tile_h = H_out - oh0;
  tile_h = tile_h < TileH ? tile_h : TileH;
  int tile_w = W_out - ow0;
  tile_w = tile_w < TileW ? tile_w : TileW;

  const int inH = (TileH - 1) * stride + dilation * (K - 1) + 1;
  const int plane_size = inH * TileW;

  extern __shared__ float smem_raw[];
  float* sX_ptr = smem_raw;
  float* sW_ptr = smem_raw + 2 * plane_size;

  Tensor sX = make_tensor(
      make_smem_ptr(sX_ptr),
      make_shape(Int<2>{}, inH, Int<TileW>{}),
      make_stride(plane_size, Int<TileW>{}, Int<1>{})
  );

  Tensor sW = make_tensor(
      make_smem_ptr(sW_ptr),
      make_shape(Int<TileC>{}, K),
      make_stride(K, Int<1>{})
  );

  const int64_t x_n_stride = (int64_t)C * H * W_in;
  const int64_t x_c_stride = (int64_t)H * W_in;
  const int64_t x_h_stride = (int64_t)W_in;

  const int64_t y_n_stride = (int64_t)C * H_out * W_out;
  const int64_t y_c_stride = (int64_t)H_out * W_out;
  const int64_t y_h_stride = (int64_t)W_out;

  Tensor mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * x_n_stride),
      make_shape(C, H, W_in),
      make_stride(x_c_stride, x_h_stride, Int<1>{})
  );

  Tensor mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(C, K),
      make_stride(K, Int<1>{})
  );

  Tensor mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * y_n_stride),
      make_shape(C, H_out, W_out),
      make_stride(y_c_stride, y_h_stride, Int<1>{})
  );

  const int input_row0 = oh0 * stride - padding;
  const int input_col0 = ow0 * stride - padding;

  const bool vec_stage_ok =
      (stride == 1) &&
      (input_col0 >= 0) &&
      ((input_col0 & 3) == 0) &&
      ((W_in & 3) == 0) &&
      (input_col0 + TileW <= W_in);
  auto stage_plane = [&](int cc, int buf) {
    const int c = c_base + cc;
    const bool c_ok = (c < C);
    if (vec_stage_ok) {
      constexpr int VecPerRow = TileW / 4;
      const int vec_plane = inH * VecPerRow;
      for (int idx = tid; idx < vec_plane; idx += Threads) {
        const int ih = idx / VecPerRow;
        const int iv = idx - ih * VecPerRow;
        const int gi_h = input_row0 + ih;
        const int gi_w = input_col0 + iv * 4;
        const bool ok = c_ok && ((unsigned)gi_h < (unsigned)H);
        const float* gsrc = ok ? &mX(c, gi_h, gi_w) : X;
        stage_copy_16(&sX(buf, ih, iv * 4), gsrc, ok);
      }
    } else {
      for (int idx = tid; idx < plane_size; idx += Threads) {
        const int ih = idx / TileW;
        const int iw = idx - ih * TileW;
        const int gi_h = input_row0 + ih;
        const int gi_w = input_col0 + iw * stride;
        const bool ok = c_ok && ((unsigned)gi_h < (unsigned)H) &&
                        ((unsigned)gi_w < (unsigned)W_in);
        const float* gsrc = ok ? &mX(c, gi_h, gi_w) : X;
        stage_copy_4(&sX(buf, ih, iw), gsrc, ok);
      }
    }
  };
  // Prologue: asynchronously stage the first two channel planes into the
  // double-buffered shared-memory tiles before the pipelined compute loop.
  stage_plane(0, 0);
  cp_async_commit();
  if (TileC > 1) {
    stage_plane(1, 1);
    cp_async_commit();
  }

  #pragma unroll
  for (int cc = 0; cc < TileC; ++cc) {
    const int c = c_base + cc;
    for (int kk = tid; kk < K; kk += Threads) {
      float v = 0.0f;
      if (c < C) {
        v = (float)mW(c, kk);
      }
      sW(cc, kk) = v;
    }
  }

  float bias_vals[TileC];
  #pragma unroll
  for (int cc = 0; cc < TileC; ++cc) {
    const int c = c_base + cc;
    bias_vals[cc] = (B != nullptr && c < C) ? (float)B[c] : 0.0f;
  }

  const int qv = tid - (tid / QThreads) * QThreads;
  const int row_group = tid / QThreads;
  const int r_base = row_group * PVec;
  const int q0 = qv * VecOut;
  int oh_arr[PVec];
  int row_base_arr[PVec];
  bool row_valid_arr[PVec];
  bool col_valid_arr[VecOut];
  bool vec_store_ok;
  #pragma unroll
  for (int v = 0; v < VecOut; ++v) {
    col_valid_arr[v] = (q0 + v) < tile_w;
  }
  vec_store_ok = ((W_out & 3) == 0) && ((q0 + VecOut) <= tile_w);
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    const int r = r_base + i;
    oh_arr[i] = oh0 + r;
    row_base_arr[i] = r * stride;
    row_valid_arr[i] = (r < tile_h);
  }

  #pragma unroll
  for (int cc = 0; cc < TileC; ++cc) {
    const int buf = cc & 1;
    if (cc + 1 < TileC) {
      dw_cp_async_wait<1>();
    } else {
      dw_cp_async_wait<0>();
    }
    __syncthreads();
    const int c = c_base + cc;
    if (c < C) {
      if (K == 3 && stride == 1 && dilation == 1) {
        const float w0 = (float)sW(cc, 0);
        const float w1 = (float)sW(cc, 1);
        const float w2 = (float)sW(cc, 2);
        float xreg[VecOut][PVec + 2];
        #pragma unroll
        for (int j = 0; j < PVec + 2; ++j) {
          const float4 xv =
              *reinterpret_cast<const float4*>(&sX(buf, r_base + j, q0));
          xreg[0][j] = xv.x;
          xreg[1][j] = xv.y;
          xreg[2][j] = xv.z;
          xreg[3][j] = xv.w;
        }
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          if (!row_valid_arr[i]) continue;
          float accv[VecOut];
          #pragma unroll
          for (int v = 0; v < VecOut; ++v) {
            float acc = bias_vals[cc];
            acc += xreg[v][i]     * w0;
            acc += xreg[v][i + 1] * w1;
            acc += xreg[v][i + 2] * w2;
            accv[v] = acc;
          }
          if (vec_store_ok) {
            *reinterpret_cast<float4*>(&mY(c, oh_arr[i], ow0 + q0)) =
                make_float4(accv[0], accv[1], accv[2], accv[3]);
          } else {
            #pragma unroll
            for (int v = 0; v < VecOut; ++v) {
              if (col_valid_arr[v]) {
                mY(c, oh_arr[i], ow0 + q0 + v) = static_cast<T>(accv[v]);
              }
            }
          }
        }
      } else {
        #pragma unroll
        for (int i = 0; i < PVec; ++i) {
          if (!row_valid_arr[i]) continue;
          float accv[VecOut];
          const int rb = row_base_arr[i];
          float acc0 = bias_vals[cc];
          float acc1 = bias_vals[cc];
          float acc2 = bias_vals[cc];
          float acc3 = bias_vals[cc];
          for (int kk = 0; kk < K; ++kk) {
            const float wk = (float)sW(cc, kk);
            const float4 xv = *reinterpret_cast<const float4*>(
                &sX(buf, rb + kk * dilation, q0));
            acc0 += xv.x * wk;
            acc1 += xv.y * wk;
            acc2 += xv.z * wk;
            acc3 += xv.w * wk;
          }
          accv[0] = acc0;
          accv[1] = acc1;
          accv[2] = acc2;
          accv[3] = acc3;
          if (vec_store_ok) {
            *reinterpret_cast<float4*>(&mY(c, oh_arr[i], ow0 + q0)) =
                make_float4(accv[0], accv[1], accv[2], accv[3]);
          } else {
            #pragma unroll
            for (int v = 0; v < VecOut; ++v) {
              if (col_valid_arr[v]) {
                mY(c, oh_arr[i], ow0 + q0 + v) = static_cast<T>(accv[v]);
              }
            }
          }
        }
      }
    }
    __syncthreads();
    if (cc + 2 < TileC) {
      stage_plane(cc + 2, buf);
      cp_async_commit();
    }
  }
}

torch::Tensor depthwise2d_vertical_forward(torch::Tensor x,
                                           torch::Tensor w,
                                           c10::optional<torch::Tensor> b,
                                           int64_t stride,
                                           int64_t padding,
                                           int64_t dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(w.is_cuda(), "w must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  TORCH_CHECK(x.dim() == 4, "x must have shape [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must have shape [C, 1, K, 1]");
  TORCH_CHECK(stride > 0, "stride must be positive");
  TORCH_CHECK(padding >= 0, "padding must be non-negative");
  TORCH_CHECK(dilation > 0, "dilation must be positive");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  const int64_t N = x_c.size(0);
  const int64_t C = x_c.size(1);
  const int64_t H = x_c.size(2);
  const int64_t W_in = x_c.size(3);
  const int64_t K = w_c.size(2);

  TORCH_CHECK(w_c.size(0) == C, "w.size(0) must equal the input channels");
  TORCH_CHECK(w_c.size(1) == 1, "depthwise weight must have w.size(1) == 1");
  TORCH_CHECK(w_c.size(3) == 1, "this kernel expects a vertical Kx1 filter");
  TORCH_CHECK(N > 0 && C > 0 && H > 0 && W_in > 0 && K > 0,
              "all tensor dimensions must be positive");
  TORCH_CHECK(N <= INT_MAX && C <= INT_MAX && H <= INT_MAX &&
              W_in <= INT_MAX && K <= INT_MAX,
              "tensor dimensions are too large");

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.is_cuda(), "bias must be a CUDA tensor");
    TORCH_CHECK(b_c.scalar_type() == at::kFloat, "bias must be float32");
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == C, "bias must have shape [C]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto floor_div = [](int64_t a, int64_t divisor) -> int64_t {
    return a >= 0 ? a / divisor : -((-a + divisor - 1) / divisor);
  };

  const int64_t H_out =
      floor_div(H + 2 * padding - dilation * (K - 1) - 1, stride) + 1;
  const int64_t W_out =
      floor_div(W_in + 2 * padding - 1, stride) + 1;

  TORCH_CHECK(H_out > 0 && W_out > 0, "invalid convolution output size");
  TORCH_CHECK(H_out <= INT_MAX && W_out <= INT_MAX,
              "output dimensions are too large");

  auto y = torch::empty({N, C, H_out, W_out}, x_c.options());

  constexpr int Threads = 256;
  constexpr int TileH = 32;
  constexpr int TileW = 128;
  constexpr int TileC = 8;

  const int64_t inH64 =
      (int64_t)(TileH - 1) * stride + dilation * (K - 1) + 1;
  TORCH_CHECK(inH64 > 0 && inH64 <= INT_MAX / TileW,
              "convolution tile is too large");

  const int64_t plane64 = inH64 * TileW;
  const int64_t smem64 =
      ((int64_t)2 * plane64 + (int64_t)TileC * K) * (int64_t)sizeof(float);
  TORCH_CHECK(smem64 > 0 && smem64 <= INT_MAX,
              "dynamic shared-memory size is too large");

  const size_t smem_bytes = (size_t)smem64;

  if (smem_bytes > 48 * 1024) {
    int device = -1;
    auto dev_err = cudaGetDevice(&device);
    TORCH_CHECK(dev_err == cudaSuccess,
                "cudaGetDevice failed: ", cudaGetErrorString(dev_err));

    int max_optin_smem = 0;
    auto attr_query_err = cudaDeviceGetAttribute(
        &max_optin_smem,
        cudaDevAttrMaxSharedMemoryPerBlockOptin,
        device);
    TORCH_CHECK(attr_query_err == cudaSuccess,
                "cudaDeviceGetAttribute failed: ",
                cudaGetErrorString(attr_query_err));
    TORCH_CHECK(smem_bytes <= (size_t)max_optin_smem,
                "convolution configuration requires too much shared memory");

    auto attr_err = cudaFuncSetAttribute(
        depthwise2d_vertical_tiled_kernel<float, Threads, TileH, TileW, TileC>,
        cudaFuncAttributeMaxDynamicSharedMemorySize,
        (int)smem_bytes);
    TORCH_CHECK(attr_err == cudaSuccess,
                "cudaFuncSetAttribute failed: ",
                cudaGetErrorString(attr_err));
  }

  const int64_t h_tiles = (H_out + TileH - 1) / TileH;
  const int64_t w_tiles = (W_out + TileW - 1) / TileW;
  const int64_t c_tiles = (C + TileC - 1) / TileC;
  const int64_t spatial_blocks = h_tiles * w_tiles * N;

  TORCH_CHECK(spatial_blocks <= INT_MAX,
              "too many spatial tiles for kernel launch");
  TORCH_CHECK(c_tiles <= 65535,
              "too many channel tiles for kernel launch");

  dim3 block(Threads);
  dim3 grid((unsigned)spatial_blocks, (unsigned)c_tiles, 1);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  depthwise2d_vertical_tiled_kernel<float, Threads, TileH, TileW, TileC>
      <<<grid, block, smem_bytes, stream>>>(
          x_c.data_ptr<float>(),
          w_c.data_ptr<float>(),
          b_ptr,
          y.data_ptr<float>(),
          (int)N, (int)C, (int)H, (int)W_in,
          (int)K, (int)stride, (int)padding, (int)dilation,
          (int)H_out, (int)W_out
      );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "depthwise2d_vertical_tiled_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
